 "content": "def transform(grid):
    """Overlay the two panels, marking cells occupied in both with color 2."""
    h = len(grid)
    w = len(grid[0]) if h else 0

    # A full, uniform nonzero row or column is the panel separator.
    split = None
    for r, row in enumerate(grid):
        if row and row[0] != 0 and all(v == row[0] for v in row):
            split = ("h", r)
            break
    if split is None:
        for c in range(w):
            vals = [grid[r][c] for r in range(h)]
            if vals and vals[0] != 0 and all(v == vals[0] for v in vals):
                split = ("v", c)
                break
    if split is None:
        raise ValueError("No uniform nonzero panel separator found")

    axis, k = split
    if axis == "h":
        a, b = grid[:k], grid[k + 1:]
        if len(a) != len(b):
            raise ValueError("Horizontal panels have different heights")
        return [[2 if x != 0 and y != 0 else 0 for x, y in zip(ra, rb)]
                for ra, rb in zip(a, b)]

    left = [row[:k] for row in grid]
    right = [row[k + 1:] for row in grid]
    if any(len(a) != len(b) for a, b in zip(left, right)):
        raise ValueError("Vertical panels have different widths")
    return [[2 if x != 0 and y != 0 else 0 for x, y in zip(ra, rb)]
            for ra, rb in zip(left, right)]
